        return [x for x in nums if nums.count(x) == 1]

code.javascript:
var singleNumber = function(nums) {
    const result = [];
    for (const x of nums) {
        let count = 0;
        for (const y of nums) if (y === x) count++;
        if (count === 1) result.push(x);
    }
    return result;
};

