public:
    vector<int> singleNumber(vector<int>& nums) {
        unordered_map<int, int> count;
        for (int x : nums) count[x]++;
        vector<int> result;
        for (auto& [x, c] : count)
            if (c == 1) result.push_back(x);
        return result;
    }
};

