class Solution:
    def addBinary(self, a: str, b: str) -> str:
        out, i, j, carry = [], len(a) - 1, len(b) - 1, 0
        while i >= 0 or j >= 0 or carry:
            s = carry
            if i >= 0:
                s += int(a[i])
                i -= 1
            if j >= 0:
                s += int(b[j])
                j -= 1
            out.append(str(s & 1))
            carry = s >> 1
        return "".join(reversed(out))

