        let s = carry;
        if (i >= 0) s += a.charCodeAt(i--) - 48;
        if (j >= 0) s += b.charCodeAt(j--) - 48;
        out.push(s & 1);
        carry = s >> 1;
    }
    return out.reverse().join("");
};

