class Solution:
    def minEnd(self, n: int, x: int) -> int:
        result, rest, bit = x, n - 1, 1
        while rest:
            if not x & bit:
                if rest & 1:
                    result |= bit
                rest >>= 1
            bit <<= 1
        return result

